#if DEBUG
import Foundation
import ResoniqDiagnostics
import ResoniqStore

/// Reports for the debug screens (`ResultsDebugScreens`).
///
/// They are real `SpeakerReport`s, made by the Kit: its own simulated speaker (healthy, with a 100-160 Hz buzz; a
/// healthy one; recordings that were clipped and drowned out; a speaker with no output below 500 Hz) was run
/// through `RunAnalyzer` and `SpeakerDiagnosis`, three runs each, and the encoded reports are kept here, with the
/// numbers rounded to three decimals to keep the file small. The one exception is `notAssessed`: no simulated
/// speaker has noise that drowns only the bass, so its three runs are valid readings built by hand (a flat response,
/// clean distortion, 5 dB of signal over the noise below 200 Hz) and the report is the Kit's. The words, the
/// findings and the portrait are exactly what the Kit made.
/// To regenerate them, run those speakers through `Bench` in `ResoniqDiagnosticsTests` in a throwaway test that
/// encodes each report (sorted keys), round the numbers, paste, and delete the test. A report that no longer decodes
/// is a loud failure in a debug build, not a silent one.
enum DiagnoseFixtures {
    /// The mockup's case, as far as the Kit can say it today: healthy except a buzz at 100-160 Hz inferred in 3 of 3
    /// runs ("Possible buzz at 100-160 Hz"), and the "even" statement for the tweeter and mid tagged measured. The
    /// mockup's top-end dip is not in it: the simulated speaker has none.
    static let buzzing: SpeakerReport = decode(buzzingJSON)

    /// A speaker with nothing wrong: one "even" finding.
    static let healthy: SpeakerReport = decode(healthyJSON)

    /// Three runs that could not be used: nothing is concluded.
    static let inconclusive: SpeakerReport = decode(inconclusiveJSON)

    /// A woofer with no output: "I could barely hear the woofer", measured, and an "even" statement for the tweeter.
    static let quietWoofer: SpeakerReport = decode(quietWooferJSON)

    /// A woofer the room's noise drowned out: "Couldn't check the woofer", inconclusive, and the rest even.
    static let notAssessed: SpeakerReport = decode(notAssessedJSON)

    /// The finding the Finding screen shows.
    static var buzz: Finding { buzzing.findings.first { $0.kind == .distortion }! }

    private static func decode(_ json: String) -> SpeakerReport {
        do {
            return try JSONDecoder().decode(SpeakerReport.self, from: Data(json.utf8))
        } catch {
            fatalError("A debug fixture no longer decodes as a SpeakerReport: \(error)")
        }
    }

